{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with TickerProviderStateMixin, WidgetsBindingObserver {
  final List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _loadingNextPage = false;

  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
  late final AnimationController _fadeController;

  Future<List<CurrencyModel>>? _currencyListFuture;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // Когда экран снова получает фокус (вернулись из навигации) — перезагружаем данные.
    if (_allCurrencies.isNotEmpty) {
      _initData();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _initData() async {
    if (!mounted) return;

    setState(() {
      _allCurrencies.clear();
      _currentPage = 0;
      _hasMore = true;
      _loadingNextPage = false;
      _filteredCurrenciesNotifier.value = const <CurrencyModel>[];
    });

    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20)).then((CurrencyPage page) {
        final List<CurrencyModel> value = page.items;
        _allCurrencies.addAll(value);
        _filteredCurrenciesNotifier.value = value;
        _hasMore = page.hasMore;
        currencyRepository.saveCurrencyList(_allCurrencies);
        return value;
      });
    });

    await _currencyListFuture;
    if (mounted) {
      setState(() {});
      _fadeController.forward();
    }
  }

  Future<void> _loadMore() async {
    final int nextPage = _currentPage + 1;
    if (_hasMore && !_loadingNextPage && mounted) {
      final currencyRepository = context.read<CurrencyRepository>();

      setState(() => _loadingNextPage = true);

      try {
        final CurrencyPage paginatedData = await currencyRepository.fetchRates(
          CurrencyPageRequest(base: 'USD', page: nextPage, pageSize: 20),
        );

        if (!mounted) return;

        setState(() {
          _allCurrencies.addAll(paginatedData.items);
          _filteredCurrenciesNotifier.value = _allCurrencies.toList(growable: false);
          _currentPage = nextPage;
          _hasMore = paginatedData.hasMore;
          currencyRepository.saveCurrencyList(_allCurrencies);
        });
      } finally {
        if (mounted) {
          setState(() => _loadingNextPage = false);
        }
      }
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase().trim();
    if (lowerQuery.isEmpty) {
      _filteredCurrenciesNotifier.value = _allCurrencies.toList(growable: false);
      return;
    }
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    final Future<List<CurrencyModel>>? futureToBuild = _currencyListFuture;

    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: futureToBuild == null
          ? const SizedBox.shrink()
          : FutureBuilder<List<CurrencyModel>>(
              future: futureToBuild,
              builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
                if (!snapshot.hasData) return const SizedBox.shrink();

                return FadeTransition(
                  opacity: _fadeController.view,
                  child: Column(
                    children: [
                      Padding(
                        padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                        child: SearchView(onChanged: _filterCurrencies),
                      ),
                      Expanded(
                        child: ValueListenableBuilder<List<CurrencyModel>>(
                          valueListenable: _filteredCurrenciesNotifier,
                          builder: (BuildContext context, List<CurrencyModel> listData, _) {
                            return ListView.builder(
                              itemCount: listData.length + 1,
                              itemBuilder: (BuildContext context, int index) {
                                if (index < listData.length) {
                                  final CurrencyModel currency = listData[index];

                                  return Padding(
                                    key: ValueKey(currency.id),
                                    padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                                    child: CurrencyCard(model: currency),
                                  );
                                }

                                // Кнопка «Показать ещё» или индикатор загрузки.
                                if (!_hasMore && listData.isNotEmpty) {
                                  return const SizedBox.shrink();
                                }
                                return Padding(
                                  padding: const EdgeInsets.only(top: 16),
                                  child: Center(
                                    child: _loadingNextPage
                                        ? SizedBox(
                                            width: 40,
                                            height: 40,
                                            child: CircularProgressIndicator(strokeWidth: 3),
                                          )
                                        : _hasMore
                                            ? FilledButton(
                                                onPressed: _loadMore,
                                                child: Text(context.loc.showMore),
                                              )
                                            : const SizedBox.shrink(),
                                  ),
                                );
                              },
                              padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                            );
                          },
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
    );
  }
}
